import { existsSync, readFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { readMigrationFiles } from "drizzle-orm/migrator";
import { migrate } from "drizzle-orm/node-postgres/migrator";

import type { Database, DatabaseConnection } from "./client.js";
import { sql } from "./index.js";

/**
 * Folder with the SQL migrations generated by drizzle-kit: `MIGRATIONS_DIR`
 * if set, else `drizzle/` next to a bundle, else the folder of this package.
 */
export function migrationsFolder(): string {
  const configured = process.env["MIGRATIONS_DIR"];
  if (configured) return configured;
  const here = dirname(fileURLToPath(import.meta.url));
  // A bundle (CLI, API image) ships the migrations next to itself.
  const bundled = resolve(here, "drizzle");
  if (existsSync(resolve(bundled, "meta/_journal.json"))) return bundled;
  return resolve(here, "../drizzle");
}

type Executor = Pick<Database, "execute">;

async function rows<T>(db: Executor, query: ReturnType<typeof sql>) {
  return ((await db.execute(query)) as { rows: T[] }).rows;
}

async function hasColumn(
  db: Executor,
  table: string,
  column: string,
): Promise<boolean> {
  const found = await rows(
    db,
    sql`select 1 from information_schema.columns
        where table_schema = 'public' and table_name = ${table}
        and column_name = ${column}`,
  );
  return found.length > 0;
}

/**
 * Migrations dated before an older one in the journal. drizzle applies only
 * migrations newer than the last one it recorded, so it skips these on a
 * database that was migrated before they came. Each entry tells whether
 * the changes of its migration are still missing.
 */
const MISDATED: Record<string, (db: Executor) => Promise<boolean>> = {
  "0002_recurring_activities": (db) => hasColumn(db, "task", "scheduled_date"),
};

/**
 * Finds the migrations drizzle skipped (not recorded, but dated before the
 * last recorded one). A known one is applied if its changes are missing,
 * then recorded. Any other one is an error: drizzle would skip it silently.
 */
async function repairSkippedMigrations(db: Database): Promise<void> {
  const [journal] = await rows<{ name: string | null }>(
    db,
    sql`select to_regclass('drizzle.__drizzle_migrations')::text as name`,
  );
  if (!journal?.name) return;
  const applied = await rows<{ hash: string; created_at: string }>(
    db,
    sql`select hash, created_at from drizzle.__drizzle_migrations`,
  );
  if (applied.length === 0) return;
  const recorded = new Set(applied.map((row) => row.hash));
  const last = Math.max(...applied.map((row) => Number(row.created_at)));

  const folder = migrationsFolder();
  const { entries } = JSON.parse(
    readFileSync(resolve(folder, "meta/_journal.json"), "utf8"),
  ) as { entries: { tag: string }[] };
  const files = readMigrationFiles({ migrationsFolder: folder });

  for (const [i, file] of files.entries()) {
    if (recorded.has(file.hash) || file.folderMillis > last) continue;
    const tag = entries[i]?.tag ?? String(i);
    const missing = MISDATED[tag];
    if (!missing) {
      throw new Error(
        `Migration ${tag} was skipped: it is dated before a migration ` +
          "the database already has. Add a repair for it to MISDATED.",
      );
    }
    await db.transaction(async (tx) => {
      if (await missing(tx)) {
        for (const statement of file.sql) await tx.execute(sql.raw(statement));
      }
      await tx.execute(
        sql`insert into drizzle.__drizzle_migrations (hash, created_at)
            values (${file.hash}, ${file.folderMillis})`,
      );
    });
  }
}

/**
 * Applies all pending migrations, also those drizzle skipped because of
 * their date. Used by the CLI, the desktop app and `pnpm db:migrate`.
 */
export async function migrateDatabase(
  connection: Pick<DatabaseConnection, "db">,
): Promise<void> {
  await repairSkippedMigrations(connection.db);
  // The node-postgres migrator accepts any database of that driver.
  await migrate(connection.db as Parameters<typeof migrate>[0], {
    migrationsFolder: migrationsFolder(),
  });
}
